input.script:
export const meta = {
  name: 'codebase-docs-drift-review',
  description: 'Audit .planning/codebase/*.md for staleness vs the live code, adversarially verify each drift finding, and apply only confirmed fixes',
  phases: [
    { title: 'Audit', detail: 'one agent per doc verifies claims against live code' },
    { title: 'Verify', detail: 'adversarial confirm of each drift finding' },
    { title: 'Update', detail: 'apply confirmed fixes per doc' },
  ],
}

const TODAY = '2026-06-19'
const DIR = '.planning/codebase'

const DOCS = [
  {
    name: 'STACK.md',
    focus: `Verify EVERY version number and tool against actual manifests: root package.json, apps/*/package.json, packages/*/package.json, the root Cargo.toml and crates/*/Cargo.toml (and Cargo.lock for resolved versions), tsconfig.base.json, pnpm-workspace.yaml. Check listed languages, frameworks, libraries, build/dev tools and their version ranges match what is actually declared. Flag removed deps, newly-added significant deps that are missing, and version mismatches (e.g. ^5.9.3 vs actual).`,
  },
  {
    name: 'ARCHITECTURE.md',
    focus: `Verify architectural claims against code: the TS package / Rust crate hierarchy (packages/core, crypto, sdk-core, sdk, api-client; crates/*), the data model (FilePointer v2, vault key blob v2, per-folder and per-file IPNS records), encryption schemes (ECIES secp256k1, AES-256-GCM and AES-CTR), key/auth flows, TEE republish cadence, and sync model. Confirm described modules, layers, and flows still exist and are described correctly. Recent changes: SDK self-bootstrap folder tree from root IPNS key (#498), shared-folder ownership consolidation (#500), move/restore re-encryption (#507).`,
  },
  {
    name: 'STRUCTURE.md',
    focus: `Verify the directory-layout tree and per-directory descriptions against the actual filesystem. Use ls/find on apps/, packages/, crates/, tools/, scripts/, docker/, tests/. Flag: directories or files in the tree that no longer exist, notable new top-level or subdirectories that are missing from the tree, and mis-described module responsibilities. Be precise about paths.`,
  },
  {
    name: 'CONVENTIONS.md',
    focus: `THIS IS THE OLDEST DOC (last content change 2026-03-30) — scrutinize. Verify: tsconfig.base.json compiler options (target/module/moduleResolution/strict flags), ESLint config in eslint.config.js, prettier.config.js, commitlint.config.js (valid types + the custom no-parens-in-subject rule), naming conventions (string literals over TS enums per project rule), barrel/export patterns, error-handling and crypto-cleanup conventions, and the API-client regeneration workflow. Confirm each quoted config snippet matches the live file exactly.`,
  },
  {
    name: 'INTEGRATIONS.md',
    focus: `Verify external integrations and their config: IPFS/Kubo version (check .github/workflows/*.yml service containers AND docker/docker-compose*.yml — the doc claims ipfs/kubo:v0.40.0), Web3Auth, Phala TEE / tee-worker, env var NAMES and default values, and API endpoint paths. Grep apps/api/src controllers to confirm endpoint routes (e.g. /ipfs/upload, /ipfs/:cid, /ipfs/unpin) still exist and match. Confirm env var names match actual usage in code/config. Flag any version or route drift.`,
  },
  {
    name: 'TESTING.md',
    focus: `Verify the testing setup (last content change 2026-03-31): per-package test runners (Jest vs Vitest) and the exact config file paths in the table, test scripts in each package.json, coverage config (codecov.yml), E2E framework/setup (Playwright? where?), and CI test gating in .github/workflows. Confirm each listed config file actually exists and the framework/version is right. Note: apps/web vitest include is src/**/*.test.ts (.spec.ts is skipped) — verify the doc reflects reality.`,
  },
  {
    name: 'CONCERNS.md',
    focus: `This lists tech debt / known issues. For EACH concern: determine whether it STILL EXISTS in current code or has been RESOLVED since the 2026-03-30 analysis date. Verify every file:line reference — many will have shifted or the underlying issue been fixed. Recent landings that may have resolved concerns: SDK self-bootstrap from root IPNS key (#498), shared-folder ownership consolidation + encrypt share itemName (#500), move/restore re-encryption (#507), folder-seeding rescope (#502). Also check .planning/todos/ (if it exists) for the current tracked ledger to reconcile against. Flag RESOLVED concerns (candidates for removal/marking-done) and clearly-real NEW concerns only if obvious. A resolved-but-still-listed concern IS drift.`,
  },
]

const FINDINGS_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['doc', 'verdict', 'findings', 'notes'],
  properties: {
    doc: { type: 'string' },
    verdict: { type: 'string', enum: ['accurate', 'minor_drift', 'significant_drift'] },
    findings: {
      type: 'array',
      items: {
        type: 'object',
        additionalProperties: false,
        required: ['section', 'quote', 'issue', 'reality', 'evidence', 'severity', 'suggested_fix'],
        properties: {
          section: { type: 'string', description: 'Heading/section of the doc where the stale text lives' },
          quote: { type: 'string', description: 'EXACT verbatim text from the doc that is stale, copied so it can be used for find-and-replace' },
          issue: { type: 'string', description: 'What is wrong / why it is stale' },
          reality: { type: 'string', description: 'What the codebase actually shows now' },
          evidence: { type: 'string', description: 'Concrete file:line citations proving the current reality' },
          severity: { type: 'string', enum: ['high', 'medium', 'low'] },
          suggested_fix: { type: 'string', description: 'The corrected replacement text for the quote' },
        },
      },
    },
    notes: { type: 'string', description: 'Anything notable; if the doc is fully accurate say so explicitly' },
  },
}

const VERDICT_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['confirmed', 'corrected_fix', 'evidence', 'reason'],
  properties: {
    confirmed: { type: 'boolean', description: 'true ONLY if concrete code evidence proves the doc statement is now false/outdated' },
    corrected_fix: { type: 'string', description: 'Validated (or corrected) replacement text. If confirmed=false, empty string.' },
    evidence: { type: 'string', description: 'file:line evidence you personally verified' },
    reason: { type: 'string' },
  },
}

const UPDATE_SCHEMA = {
  type: 'object',
  additionalProperties: false,
  required: ['editsApplied', 'summary', 'unapplied'],
  properties: {
    editsApplied: { type: 'integer' },
    summary: { type: 'string', description: 'One-line-per-edit summary of what changed' },
    unapplied: { type: 'array', items: { type: 'string' }, description: 'Confirmed findings that could not be cleanly applied, with reason' },
  },
}

function auditPrompt(doc) {
  return `You are auditing a generated project doc for STALENESS (drift) against the live codebase. Repo root is the cwd; this is the CipherBox monorepo.

DOC TO AUDIT: ${DIR}/${doc.name}

1. Read the entire doc first.
2. For each checkable factual claim, verify it against the ACTUAL code/config using Read/Grep/Glob/Bash (ls, find, cat). Do not trust the doc — trust the files.

FOCUS FOR THIS DOC:
${doc.focus}

Report ONLY genuine drift — places where the doc states something that is no longer true. Do NOT report style preferences, do NOT propose rewrites of accurate content, do NOT invent improvements. Scope is tight: stale facts only.

For each finding:
- "quote" MUST be exact verbatim text copied from the doc (so it can be used as a find-and-replace target). Keep it short but unique.
- "evidence" must cite specific file:line or command output proving current reality.
- "suggested_fix" is the minimal corrected replacement for the quote — match the doc's existing format/voice.

Set "verdict": accurate (no drift), minor_drift (a few low/medium items), or significant_drift (high-severity or many items). If the doc is fully accurate, return an empty findings array and say so in notes.

Your returned object IS the data (StructuredOutput). Be thorough but precise.`
}

function verifyPrompt(doc, f) {
  return `You are an ADVERSARIAL verifier. A doc-audit agent claims the following text in ${DIR}/${doc.name} is stale. Independently check the live code and decide if this is REAL drift.

CLAIMED-STALE QUOTE (from the doc):
"""${f.quote}"""

AUDITOR'S ISSUE: ${f.issue}
AUDITOR'S CLAIMED CURRENT REALITY: ${f.reality}
AUDITOR'S EVIDENCE: ${f.evidence}
AUDITOR'S SUGGESTED FIX: ${f.suggested_fix}

Your job: verify against the ACTUAL files yourself (Read/Grep/Glob/Bash). Be conservative — a false confirmation causes a wrong doc edit.

Set confirmed=true ONLY if you personally find concrete evidence that the doc's statement is now FALSE or outdated. If the doc is still accurate, the evidence is ambiguous, or you cannot independently verify the new reality, set confirmed=false.

If confirmed=true, return "corrected_fix" — the precise replacement text you verified is correct (fix the auditor's suggested_fix if it is wrong or imprecise). Cite the file:line evidence YOU checked.`
}

function updatePrompt(doc, confirmed) {
  const items = confirmed.map((c, i) => `### Fix ${i + 1} (section: ${c.section}, severity: ${c.severity})
FIND (verbatim in doc):
"""${c.quote}"""
REPLACE WITH:
"""${c.verdict.corrected_fix || c.suggested_fix}"""
WHY: ${c.issue}`).join('\n\n')

  return `Apply ONLY these verified drift fixes to ${DIR}/${doc.name}. Read the file first, then make each replacement with the Edit tool.

STRICT RULES:
- Change ONLY the text identified below. Do not rewrite, reformat, reorder, or "improve" any other content. Tight scope.
- Match the doc's existing markdown style (heading levels, list style, code fences, table format). Keep blank lines around lists/code blocks consistent.
- If a FIND string is not present verbatim, locate the equivalent current text and apply the intended correction; if you genuinely cannot locate it, list it under "unapplied" with the reason instead of guessing.
- Under the doc's "**Analysis Date:**" line, add (or update if already present) a single line: "**Drift review:** ${TODAY}" — do this ONLY because you are making content edits to this doc.

FIXES:
${items}

Return editsApplied (count of replacements actually made), a one-line-per-edit summary, and any unapplied items.`
}

phase('Audit')
const results = await pipeline(
  DOCS,
  (doc) => agent(auditPrompt(doc), { label: `audit:${doc.name}`, phase: 'Audit', schema: FINDINGS_SCHEMA }),
  async (audit, doc) => {
    const findings = (audit && audit.findings) || []
    if (!findings.length) {
      return {
        doc: doc.name,
        auditVerdict: audit ? audit.verdict : 'unknown',
        findingsCount: 0,
        confirmedCount: 0,
        confirmed: [],
        update: { editsApplied: 0, summary: 'No drift found — doc verified accurate.', unapplied: [] },
        notes: audit ? audit.notes : 'audit agent returned null',
      }
    }
    const verdicts = await parallel(findings.map((f, i) => () =>
      agent(verifyPrompt(doc, f), { label: `verify:${doc.name}#${i + 1}`, phase: 'Verify', schema: VERDICT_SCHEMA })
        .then(v => ({ ...f, verdict: v || { confirmed: false, corrected_fix: '', evidence: '', reason: 'verifier returned null' } }))
    ))
    const confirmed = verdicts.filter(Boolean).filter(x => x.verdict && x.verdict.confirmed)
    if (!confirmed.length) {
      return {
        doc: doc.name,
        auditVerdict: audit.verdict,
        findingsCount: findings.length,
        confirmedCount: 0,
        confirmed: [],
        update: { editsApplied: 0, summary: 'All candidate findings rejected by adversarial verifier — no edits made.', unapplied: [] },
        notes: audit.notes,
      }
    }
    const update = await agent(updatePrompt(doc, confirmed), { label: `update:${doc.name}`, phase: 'Update', schema: UPDATE_SCHEMA })
    return {
      doc: doc.name,
      auditVerdict: audit.verdict,
      findingsCount: findings.length,
      confirmedCount: confirmed.length,
      confirmed: confirmed.map(c => ({
        section: c.section,
        severity: c.severity,
        issue: c.issue,
        fix: c.verdict.corrected_fix || c.suggested_fix,
      })),
      update: update || { editsApplied: 0, summary: 'update agent returned null', unapplied: [] },
      notes: audit.notes,
    }
  }
)

return results
